import {positions,checkedAt} from './positions.mjs?v=product-03';
import {PROFILE_KEY,profile,terms,match} from './matching.mjs?v=product-03';
import {KEY,parseBackup,backup,validateRecord,safeUrl,validDate,daysLeft} from './core.mjs';
const $=s=>document.querySelector(s),el=(tag,text,cls)=>{const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n;};
let jobs=positions,p=profile({}),saved=[],savedOnly=false,blocked=false;
const JOBS_KEY='doctoral-compass-imported-v1';
function toast(message){$('#toast').textContent=message;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',6000);}
function checkJobs(rows){if(!Array.isArray(rows)||rows.length>500)throw Error('岗位最多 500 条');const ids=new Set();return rows.map(j=>{if(!j||typeof j!=='object')throw Error('岗位格式错误');const out={};for(const key of ['id','title','institution','short','country','city','field','degree','language','funding','salary','deadline','summary','requirements','caution','url']){if(typeof j[key]!=='string'||j[key].length>2500)throw Error('岗位字段不完整：'+key);out[key]=j[key];}if(!/^[A-Za-z0-9_-]+$/.test(j.id)||!validDate(j.deadline)||ids.has(j.id)||!['master','master_or_exception','unknown'].includes(j.degree))throw Error('岗位 ID、日期或学历类型错误');ids.add(j.id);out.url=safeUrl(j.url);if(!out.url)throw Error('必须提供岗位原始来源');for(const key of ['topics','methods']){if(!Array.isArray(j[key])||j[key].length>40||j[key].some(s=>typeof s!=='string'||s.length>100))throw Error('关键词格式错误');out[key]=j[key];}return out;});}
try{const raw=localStorage.getItem(PROFILE_KEY);if(raw)p=profile(JSON.parse(raw));const b=localStorage.getItem(KEY);if(b)saved=parseBackup(b);const j=localStorage.getItem(JOBS_KEY);if(j)jobs=checkJobs(JSON.parse(j));}catch{blocked=true;toast('本地已有数据无法读取，已禁用写入以避免覆盖。请先恢复备份。');}
function isSaved(j){return saved.some(s=>s.id==='radar-'+j.id);}
function saveJob(j){if(blocked)return toast('需要先恢复本地数据');if(isSaved(j))return toast('已在申请清单中保留，不重复添加。');try{const record=validateRecord({id:'radar-'+j.id,title:j.title,institution:j.institution,country:j.country,type:'PhD',deadline:j.deadline,stage:'saved',url:j.url,verified:false,notes:'公开快照；请自行核对官方要求。'+j.caution,materials:[{label:'CV',status:'missing'},{label:'动机信',status:'missing'}],history:[{at:new Date().toISOString(),action:'从公开快照手动收藏'}]});const next=[...saved,record];localStorage.setItem(KEY,backup(next));saved=next;render();toast('已加入申请清单；未进行投递。');}catch(e){toast('未保存：'+e.message);}}
function options(){for(const [id,key,label] of [['country','country','所有国家'],['field','field','所有领域']]){const v=$('#'+id).value;$('#'+id).replaceChildren();const o=el('option',label);o.value='all';$('#'+id).append(o);for(const x of [...new Set(jobs.map(j=>j[key]))].sort()){const opt=el('option',x);opt.value=x;$('#'+id).append(opt);}$('#'+id).value=[...$('#'+id).options].some(x=>x.value===v)?v:'all';}}
function render(){options();$('#snapshot-count').textContent=jobs.length;$('#country-count').textContent=new Set(jobs.map(j=>j.country)).size;$('#checked').textContent=jobs===positions?checkedAt:'本地导入（未经本站核验）';$('#saved-count').textContent=saved.length;
 const set=!!(terms(p.topics).length||terms(p.methods).length);$('#profile-heading').textContent=set?'从你的方向，重新看机会。':'从你的兴趣出发。';$('#profile-summary').textContent=set?'兴趣：'+(p.topics||'未填')+'；方法：'+(p.methods||'未填'):'填写兴趣、方法与地区偏好，查看关键词重合和申请条件缺口。不需要上传 CV。';
 const q=$('#search').value.trim().toLowerCase(),today=new Date().toISOString().slice(0,10);let rows=jobs.map(j=>({j,m:match(j,p,today)})).filter(({j,m})=>!savedOnly||isSaved(j)).filter(({j})=>!$('#focus-social').checked||j.field==='社会科学与治理').filter(({j,m})=>!$('#hide-expired').checked||!m.expired).filter(({j})=>$('#country').value==='all'||j.country===$('#country').value).filter(({j})=>$('#field').value==='all'||j.field===$('#field').value).filter(({j})=>[j.title,j.institution,j.short,j.country,j.city,j.field,j.summary,...j.topics,...j.methods].join(' ').toLowerCase().includes(q)).filter(({j})=>{const v=$('#deadline').value,d=daysLeft(j.deadline);return v==='all'||d!==null&&(v==='long'?d>=30:d>=0&&d<=Number(v));});
 if($('#sort').value==='match')rows.sort((a,b)=>(b.m.score??-1)-(a.m.score??-1));if($('#sort').value==='deadline')rows.sort((a,b)=>(a.j.deadline||'9999').localeCompare(b.j.deadline||'9999'));
 $('#results-count').textContent=rows.length;$('#results-note').textContent=savedOnly?'这里只显示快照中已收藏的岗位；所有自建记录在申请清单。':set?'关键词重合用于探索；点击详情查看原因和资格缺口。':'先浏览岗位，再设置自己的匹配档案。';$('#list').replaceChildren();
 if(!rows.length){const box=el('div',undefined,'empty');box.append(el('strong','暂时没有符合条件的岗位'),'试试调整筛选，或导入你自己核验的岗位快照。');$('#list').append(box);}
 for(const {j,m} of rows){const card=el('article',undefined,'job'),logo=el('div',j.short.slice(0,1),'institution-logo '+(j.country==='奥地利'?'vienna':'')),body=el('div'),meta=el('div',undefined,'meta');meta.append(el('span',j.institution),el('span','· '+j.city+' / '+j.country),el('span',jobs===positions?'● 官方页快照':'○ 本地导入','source-dot'));const tags=el('div',undefined,'tags');tags.append(el('span',j.field,'tag field'),el('span',j.funding,'tag'));for(const t of j.topics.filter(t=>/[\u4e00-\u9fff]/.test(t)).slice(0,2))tags.append(el('span',t,'tag'));body.append(meta,el('h3',j.title),el('p',j.summary,'summary'),tags,el('div',j.salary,'salary'),el('div','截止 '+(j.deadline||'未编码')+' · '+(j.language==='unknown'?'语言需核验':j.language),'deadline'));const side=el('div',undefined,'job-side');if(m.score!==null){const n=el('div',String(m.score),'score');n.append(el('small',' / 100'));side.append(n,el('div',m.label,'score-label'));}else side.append(el('div','未设置匹配','unscored'),el('div','先填写你的方向','score-label'));side.append(el('div',m.checks.filter(c=>['gap','unknown'].includes(c.state)).length+' 项缺口 / 未知','gap-note'));const actions=el('div',undefined,'side-actions'),detail=el('button','查看详情','detail'),save=el('button',isSaved(j)?'已收藏':'＋ 收藏',isSaved(j)?'saved':'');detail.onclick=()=>show(j,m);save.onclick=()=>saveJob(j);actions.append(detail,save);side.append(actions);const reasons=el('div',undefined,'match-reasons');reasons.append(el('strong','匹配依据'),el('span',m.score===null?'填入兴趣与方法后显示；不上传 CV。':m.overlap.length?'命中：'+m.overlap.join('、'):'已填关键词暂无命中，不代表不适合。'));body.append(reasons);card.append(logo,body,side);$('#list').append(card);}
}
function show(j,m){$('#job-title').textContent=j.title;const b=$('#job-body');b.replaceChildren();for(const [title,text] of [['研究内容',j.summary],['官方要求的简要整理',j.requirements],['需要特别核对',j.caution]]){const s=el('section',undefined,'detail-block');s.append(el('h3',title),el('p',text));b.append(s);}const review=el('section',undefined,'detail-block');review.append(el('h3','申请前核对清单'),el('p','① 专业与学位取得时间　② 英语及当地语言　③ 资助／流动限制　④ 材料与当地截止时点。本站不替你核验或自动投递。'));b.append(review);const explain=el('section',undefined,'detail-block');explain.append(el('h3','兴趣匹配 · '+(m.score===null?'尚未填写档案':m.score+' / 100')));if(!m.components.length)explain.append(el('p','没有档案时不生成分数。'));for(const c of m.components){const row=el('div',undefined,'component');row.append(el('span',c.label+'：'+(c.hits.join('、')||'未命中')),el('strong',c.points+' / '+c.max));explain.append(row);}explain.append(el('p','基于已编码词表的重合，不是语义理解或录取概率。没命中不代表不适合。'));b.append(explain);const gates=el('section',undefined,'detail-block');gates.append(el('h3','申请条件 · 独立核验，不计入兴趣分'));for(const c of m.checks){const row=el('div',undefined,'check-row');row.dataset.state=c.state;row.append(el('strong',c.label),el('span',c.text));gates.append(row);}b.append(gates);const link=el('a','打开官方原始招聘页 ↗','detail-link');link.href=j.url;link.target='_blank';link.rel='noopener noreferrer';b.append(link);$('#job-dialog').showModal();}
function openProfile(){const f=$('#profile-form').elements;for(const k of ['topics','methods','degree','english'])f[k].value=p[k];f.countries.value=p.countries.join(', ');$('#profile-dialog').showModal();}
for(const id of ['profile-open','profile-hero','profile-search'])$('#'+id).onclick=openProfile;
$('#profile-close').onclick=()=>$('#profile-dialog').close();$('#job-close').onclick=()=>$('#job-dialog').close();$('#profile-form').onsubmit=e=>{e.preventDefault();if(blocked)return toast('需要先恢复本地数据');try{const f=e.currentTarget.elements,next=profile({topics:f.topics.value,methods:f.methods.value,degree:f.degree.value,english:f.english.value,countries:terms(f.countries.value)});localStorage.setItem(PROFILE_KEY,JSON.stringify(next));p=next;$('#profile-dialog').close();$('#sort').value='match';render();toast('档案只保存在本浏览器；未上传。');}catch(err){toast('未保存：'+err.message);}};
$('#clear-profile').onclick=()=>{if(!confirm('清空本浏览器的匹配档案？不会删除申请清单。'))return;try{localStorage.removeItem(PROFILE_KEY);p=profile({});$('#profile-dialog').close();render();}catch{toast('无法清空浏览器存储');}};
for(const id of ['search','country','field','deadline','hide-expired','sort','focus-social'])$('#'+id).addEventListener('input',()=>{if(id==='field'&&!['all','社会科学与治理'].includes($('#field').value))$('#focus-social').checked=false;render();});
$('#reset').onclick=()=>{$('#focus-social').checked=false;$('#hide-expired').checked=true;$('#country').value='all';$('#field').value='all';$('#deadline').value='all';$('#search').value='';$('#sort').value='default';render();};$('#saved-tab').onclick=()=>{savedOnly=true;$('#saved-tab').classList.add('current');$('#discover').classList.remove('current');render();};$('#discover').onclick=()=>{savedOnly=false;$('#discover').classList.add('current');$('#saved-tab').classList.remove('current');render();};
$('#data-info').onclick=()=>alert('这是 9 条人工整理的官方招聘页快照，核对日 2026-10-15。不是实时或全欧洲岗位库。中文摘要与标签由本项目整理，薪资只显示原帖税前信息或基数，不估算到手收入。没有抓取或转载参考雷达站的数据。导入岗位后，导入者负责其来源、使用许可和正确性。');
$('#import-jobs').onclick=()=>$('#jobs-file').click();$('#jobs-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(blocked||file.size>1500000)throw Error('无法导入：存储异常或文件超过 1.5 MB');const rows=checkJobs(JSON.parse(await file.text()));if(!confirm('将用导入快照替换当前浏览岗位列表。匹配档案与申请清单不受影响；请先导出原快照。继续？'))return;localStorage.setItem(JOBS_KEY,JSON.stringify(rows));jobs=rows;render();}catch(err){toast(err.message);}finally{e.target.value='';}};
$('#export-jobs').onclick=()=>{const u=URL.createObjectURL(new Blob([JSON.stringify(jobs,null,2)],{type:'application/json'})),a=el('a');a.href=u;a.download='nextposition-positions.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);};render();
